<?php require_once '../includes/bootstrap.php'; require_role('admin'); $pdo=db(); $counts=['users'=>(int)$pdo->query('SELECT COUNT(*) FROM users')->fetchColumn(),'courses'=>(int)$pdo->query('SELECT COUNT(*) FROM courses')->fetchColumn(),'enrolments'=>(int)$pdo->query('SELECT COUNT(*) FROM enrollments')->fetchColumn(),'messages'=>(int)$pdo->query('SELECT COUNT(*) FROM contacts')->fetchColumn()];$courses=$pdo->query('SELECT * FROM courses ORDER BY id DESC')->fetchAll();$messages=$pdo->query('SELECT * FROM contacts ORDER BY created_at DESC LIMIT 10')->fetchAll(); page_head('Admin Dashboard','Administrator dashboard for managing users, courses and enquiries.');site_header();render_flash(); ?>
<main><section class="page-hero"><div class="page-hero-content"><p class="section-label">ADMINISTRATION</p><h1>Management dashboard</h1><p>Role-restricted tools for managing the dynamic learning platform.</p></div></section><section><div class="stats-grid"><div class="stat-card"><strong><?= $counts['users'] ?></strong><span>Users</span></div><div class="stat-card"><strong><?= $counts['courses'] ?></strong><span>Courses</span></div><div class="stat-card"><strong><?= $counts['enrolments'] ?></strong><span>Enrolments</span></div><div class="stat-card"><strong><?= $counts['messages'] ?></strong><span>Messages</span></div></div></section><section class="alt-section"><div class="section-heading left"><p class="section-label">CRUD</p><h2>Course management</h2><p>Create, update or remove course records.</p></div><a class="button primary-button" href="<?= e(url('admin/course_edit.php')) ?>">Add course</a><div class="table-wrap"><table><caption>Course records</caption><thead><tr><th>Title</th><th>Level</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($courses as $c): ?><tr><td><?= e($c['title']) ?></td><td><?= e($c['level']) ?></td><td><?= $c['is_active']?'Active':'Inactive' ?></td><td><a href="<?= e(url('admin/course_edit.php?id='.$c['id'])) ?>">Edit</a> · <a href="<?= e(url('admin/course_delete.php?id='.$c['id'].'&csrf='.urlencode(csrf_token()))) ?>" onclick="return confirm('Delete this course?')">Delete</a></td></tr><?php endforeach; ?></tbody></table></div></section><section><div class="section-heading left"><p class="section-label">ENQUIRIES</p><h2>Recent contact messages</h2></div><div class="table-wrap"><table><caption>Recent enquiries</caption><thead><tr><th>Name</th><th>Email</th><th>Subject</th><th>Date</th></tr></thead><tbody><?php foreach($messages as $m): ?><tr><td><?= e($m['name']) ?></td><td><?= e($m['email']) ?></td><td><?= e($m['subject']) ?></td><td><?= e(date('d M Y',strtotime($m['created_at']))) ?></td></tr><?php endforeach; ?></tbody></table></div></section></main><?php site_footer(); ?>